export type OpenAIChatCompletionsProviderOptions<
  MODEL extends keyof OpenAIChatCompletionsProviderOptionsByModel | ChatModelIds | (string & {}) =
    string,
> = MODEL extends keyof OpenAIChatCompletionsProviderOptionsByModel
  ? OpenAIChatCompletionsProviderOptionsByModel[MODEL]
  : MODEL extends keyof ChatWrongModels
    ? ChatWrongModels[MODEL]
    : ChatBase;

/** The registry entry of this provider. */
export type Provider = {
  optionsKey: never;
  defaultTarget: 'responses';
  targets: {
    responses: {
      base: ResponsesBase;
      byModel: OpenAITextProviderOptionsByModel;
      modelIds: ResponsesModelIds;
      wrongModels: ResponsesWrongModels;
    };
    chat: {
      base: ChatBase;
      byModel: OpenAIChatCompletionsProviderOptionsByModel;
      modelIds: ChatModelIds;
      wrongModels: ChatWrongModels;
    };
  };
};
